-- Production PostgreSQL schema. Local reference runtime uses Node SQLite for zero-dependency boot.
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE candidate_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE NOT NULL REFERENCES users(id), profile jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE resumes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), label text NOT NULL, object_key text, parsed jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, domain text, metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE job_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_type text NOT NULL, external_key text NOT NULL, config jsonb NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true, UNIQUE(source_type, external_key));
CREATE TABLE listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), canonical_key text UNIQUE NOT NULL, company_id uuid REFERENCES companies(id), source_id uuid REFERENCES job_sources(id), external_id text, title text NOT NULL, location text, workplace text, salary_min integer, salary_max integer, currency text, description text NOT NULL, skills jsonb NOT NULL DEFAULT '[]', source_url text, posted_at timestamptz, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX listings_active_posted_idx ON listings(active, posted_at DESC);
CREATE TABLE listing_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES listings(id), content_hash text NOT NULL, payload jsonb NOT NULL, captured_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE candidate_matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), listing_id uuid NOT NULL REFERENCES listings(id), score integer NOT NULL, components jsonb NOT NULL, reasons jsonb NOT NULL, computed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,listing_id));
CREATE TABLE pipeline_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), listing_id uuid NOT NULL REFERENCES listings(id), stage text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,listing_id));
CREATE TABLE pipeline_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pipeline_job_id uuid NOT NULL REFERENCES pipeline_jobs(id), event_type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE application_packs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), listing_id uuid NOT NULL REFERENCES listings(id), resume jsonb NOT NULL, cover_letter text, screening_answers jsonb NOT NULL DEFAULT '[]', evidence jsonb NOT NULL DEFAULT '[]', verification jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE application_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), listing_id uuid NOT NULL REFERENCES listings(id), pack_id uuid REFERENCES application_packs(id), mode text NOT NULL, status text NOT NULL, ats text, receipt jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE human_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL REFERENCES application_attempts(id), task_type text NOT NULL, prompt text NOT NULL, status text NOT NULL DEFAULT 'open', response jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE message_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), pipeline_job_id uuid REFERENCES pipeline_jobs(id), subject text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES message_threads(id), direction text NOT NULL, sender text, body text NOT NULL, classification text, received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ingestion_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid REFERENCES job_sources(id), status text NOT NULL, discovered integer NOT NULL DEFAULT 0, upserted integer NOT NULL DEFAULT 0, error text, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), actor_type text NOT NULL, action text NOT NULL, subject_type text, subject_id text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
